create extension if not exists postgis with schema extensions;
create extension if not exists pgcrypto with schema extensions;
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null check(length(display_name) between 1 and 60), color text not null default '#377d64' check(color ~ '^#[0-9a-fA-F]{6}$'), created_at timestamptz not null default now());
create table public.species (id uuid primary key default gen_random_uuid(), name text unique not null, description text not null default '', thirst_pct numeric, recovery_pct numeric, created_at timestamptz not null default now(), check(thirst_pct >= 0 and recovery_pct <= 100 and thirst_pct < recovery_pct));
create table public.territories (id uuid primary key default gen_random_uuid(), name text not null, boundary extensions.geometry(Polygon,4326) not null, owner_id uuid references profiles, created_at timestamptz not null default now());
create table public.trees (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 80), species_id uuid references species, territory_id uuid not null references territories, location extensions.geography(Point,4326) not null, photo_path text, owner_id uuid references profiles, status text not null default 'unknown' check(status in ('healthy','thirsty','unknown','dead','inactive')), moisture numeric, temperature numeric, reading_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.devices (id uuid primary key default gen_random_uuid(), tree_id uuid not null unique references trees, key_hash text not null, can_report_health boolean not null default false, revoked_at timestamptz, created_at timestamptz not null default now());
create table public.sensor_readings (id uuid primary key default gen_random_uuid(), device_id uuid not null references devices, tree_id uuid not null references trees, external_event_id text not null, recorded_at timestamptz not null, soil_moisture_pct numeric not null check(soil_moisture_pct between 0 and 100), temperature_c numeric not null check(temperature_c between -60 and 85), payload jsonb not null, result jsonb, created_at timestamptz not null default now(), unique(device_id,external_event_id));
create table public.watering_requests (id uuid primary key default gen_random_uuid(), tree_id uuid not null references trees, status text not null default 'active' check(status in ('active','completed','resolved','cancelled')), created_at timestamptz not null default now(), closed_at timestamptz);
create unique index one_active_request on watering_requests(tree_id) where status='active';
create table public.watering_sessions (id uuid primary key default gen_random_uuid(), player_id uuid not null references profiles, tree_id uuid not null references trees, request_id uuid not null references watering_requests, location extensions.geography(Point,4326) not null, baseline_pct numeric not null, started_at timestamptz not null default now(), expires_at timestamptz not null, status text not null default 'active' check(status in ('active','completed','cancelled','expired')), idempotency_key uuid not null, unique(player_id,idempotency_key));
create table public.watering_events (id uuid primary key default gen_random_uuid(), device_id uuid not null references devices, tree_id uuid not null references trees, session_id uuid not null references watering_sessions, request_id uuid not null references watering_requests, external_event_id text not null, sensor_reading_id uuid not null references sensor_readings, evidence_type text not null check(evidence_type in ('moisture_increase','explicit_watering_event')), recorded_at timestamptz not null, verified boolean not null default false, completed_at timestamptz, payload jsonb not null, result jsonb, created_at timestamptz not null default now(), unique(device_id,external_event_id));
create unique index one_reward_per_request on watering_events(request_id) where completed_at is not null;
create table public.tree_health_events (id uuid primary key default gen_random_uuid(), device_id uuid not null references devices, tree_id uuid not null references trees, external_event_id text not null, status text not null check(status='dead'), recorded_at timestamptz not null, reason text not null, payload jsonb not null, result jsonb, created_at timestamptz not null default now(), unique(device_id,external_event_id));
create table public.point_events (id uuid primary key default gen_random_uuid(), player_id uuid not null references profiles, tree_id uuid not null references trees, amount integer not null, watering_event_id uuid unique references watering_events, health_event_id uuid unique references tree_health_events, created_at timestamptz not null default now(), check(num_nonnulls(watering_event_id,health_event_id)=1));
create table public.tree_dialogue (tree_id uuid primary key references trees, fingerprint text not null, message text not null, source text not null, audio_path text, audio_fingerprint text, updated_at timestamptz not null default now());
create table public.game_config (id boolean primary key default true check(id), care_points int not null default 10, death_points int not null default -20, territory_ratio numeric not null default .8 check(territory_ratio > .5 and territory_ratio <= 1), proximity_m numeric not null default 50 check(proximity_m>0), session_seconds int not null default 300 check(session_seconds>0), evidence_seconds int not null default 120 check(evidence_seconds>0), stale_seconds int not null default 1800 check(stale_seconds>0), clock_skew_seconds int not null default 30 check(clock_skew_seconds>=0), moisture_increase_pct numeric not null default 5 check(moisture_increase_pct>0), demo_mode boolean not null default false);
insert into game_config(id) values(true);
create table public.sensor_delivery_queue (id uuid primary key default gen_random_uuid(), reading_id uuid unique not null references sensor_readings, state text not null default 'pending' check(state in ('pending','leased','delivered','failed')), attempts int not null default 0, next_attempt_at timestamptz not null default now(), lease_until timestamptz, lease_token uuid, last_error text, delivered_at timestamptz, created_at timestamptz not null default now());
create index tree_location_idx on trees using gist(location);
create index territory_boundary_idx on territories using gist(boundary);
create index tree_owner_idx on trees(owner_id);
create index reading_tree_time_idx on sensor_readings(tree_id,recorded_at desc);
create index session_request_idx on watering_sessions(request_id);
create index event_session_idx on watering_events(session_id);
create index ledger_player_idx on point_events(player_id);
create index delivery_retry_idx on sensor_delivery_queue(state,next_attempt_at);
create view leaderboard with (security_invoker=true) as select p.id,p.display_name,p.color,coalesce((select sum(e.amount) from point_events e where e.player_id=p.id),0)::int points,(select count(*) from trees t where t.owner_id=p.id)::int owned_trees from profiles p;
create view tree_map with (security_invoker=true) as select t.id,t.name,t.species_id,t.territory_id,t.photo_path,t.owner_id,t.status,t.moisture,t.temperature,t.reading_at,t.updated_at,extensions.st_y(t.location::extensions.geometry) lat,extensions.st_x(t.location::extensions.geometry) lng,s.name species_name,s.thirst_pct,s.recovery_pct,r.id request_id from trees t left join species s on s.id=t.species_id left join watering_requests r on r.tree_id=t.id and r.status='active';
create view territory_map with (security_invoker=true) as select id,name,owner_id,extensions.st_asgeojson(boundary)::jsonb geojson from territories;
create function prevent_ledger_edit() returns trigger language plpgsql set search_path=public as $$begin
if current_setting('treequest.demo_reset',true)='on' and (select demo_mode from game_config) then return old; end if;
raise exception 'point ledger is append-only'; end$$;
create trigger point_ledger_immutable before update or delete on point_events for each row execute function prevent_ledger_edit();
create function new_profile() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,display_name) values(new.id,left(coalesce(new.raw_user_meta_data->>'display_name','Tree explorer'),60)); return new; end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function new_profile();
do $$declare tab text; begin
foreach tab in array array['profiles','species','territories','trees','devices','sensor_readings','watering_requests','watering_sessions','watering_events','point_events','tree_health_events','tree_dialogue','game_config','sensor_delivery_queue'] loop execute format('alter table %I enable row level security',tab); end loop;
foreach tab in array array['profiles','species','territories','trees','watering_requests','point_events','tree_dialogue','game_config'] loop execute format('create policy public_read on %I for select to anon, authenticated using (true)',tab); end loop;
end$$;
create policy own_sessions on watering_sessions for select to authenticated using(player_id=auth.uid());
create policy own_profile on profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
revoke all on all tables in schema public from anon,authenticated;
grant select on profiles,species,territories,trees,watering_requests,point_events,tree_dialogue,game_config,leaderboard,tree_map,territory_map to anon,authenticated;
grant select on watering_sessions to authenticated;
grant update(display_name,color) on profiles to authenticated;
grant all on all tables in schema public to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('tree-photos','tree-photos',true,10485760,array['image/jpeg','image/png','image/webp']),('tree-audio','tree-audio',true,10485760,array['audio/mpeg']);
create policy upload_own_photo on storage.objects for insert to authenticated with check(bucket_id='tree-photos' and (storage.foldername(name))[1]=auth.uid()::text);
create policy read_assets on storage.objects for select using(bucket_id in ('tree-photos','tree-audio'));
alter publication supabase_realtime add table trees,territories,watering_requests,point_events,watering_sessions;
